      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "O custo de extensão do apoio depende do término do marco, que não pode ser determinado sem as precedências da ficha d_a70f."
    ],
    "motivo": "As parcelas fixas permanecem, não há cobrança direta pelo aviso, mas o componente variável do apoio depende do término novo.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
